  function totals(value){if(value?.invalid)return '<p class="pm-callout">Chronologie à vérifier : aucun temps payé certain n’est affiché.</p>';if(!value)return'<p class="pm-callout">Entrée manquante : la durée reste inconnue. Aucune heure payable n’est inventée.</p>';return`<dl class="pm-totals"><div><dt>Présence brute</dt><dd>${hours(value.grossSeconds)}</dd></div><div><dt>Pause explicite</dt><dd>${hours(value.explicitBreakSeconds)}</dd></div><div><dt>Complément automatique</dt><dd>${hours(value.automaticRemainderSeconds)}</dd></div><div><dt>Temps payé</dt><dd>${hours(value.paidSeconds)}</dd></div></dl><h3>Chantiers et durées réelles</h3>${value.jobs.map(j=>`<p>JOB ${esc(job(j.jobId)?.number||'—')} · ${esc(job(j.jobId)?.name||'Chantier à confirmer')} : ${hours(j.actualSeconds)} réelles ; ${hours(j.paidSeconds)} après ventilation comptable</p>`).join('')}<p class="pm-note">Le prorata du dîner est une ventilation comptable, sans horaire de pause inventé.${value.unallocatedAccountingBreakSeconds?' Déduction non attribuée à un chantier : '+hours(value.unallocatedAccountingBreakSeconds)+'.':''}</p>`;}
